from __future__ import annotations

import ntpath
import json
from collections.abc import Mapping
from pathlib import Path
from typing import Any

from connector.runtime_protocol import (
    RuntimeConfig, RuntimeConfigSchema, RuntimeInvalidRequestError,
    RuntimeProvider, RuntimeResourceClaim, RuntimeSourceKey, RuntimeTypeDescriptor,
)
from connector.runtime_protocol.filesystem import filesystem_resource_key
from connector.runtime_protocol.host import RuntimeHostClient

from .bridge import WorkBuddyBridge

# Machine-local paths, generated by the installer.
_settings = Path(__file__).with_name("installation.json")
_installed = json.loads(_settings.read_text(encoding="utf-8-sig")) if _settings.is_file() else {
    "workspace": r"C:\Projects\WorkBuddy",
    "nodePath": r"C:\Program Files\nodejs\node.exe",
    "helperPath": str(Path(__file__).resolve().parents[2] / "bridge" / "client.cjs"),
}
WORKSPACE = ntpath.normpath(_installed["workspace"])
DEFAULTS: dict[str, Any] = {
    **_installed,
    "requestTimeoutSeconds": 45,
    "pollIntervalSeconds": 2,
}


def require_workspace(value: Any) -> str:
    if not isinstance(value, str) or not ntpath.isabs(value) or ntpath.normcase(ntpath.normpath(value)) != ntpath.normcase(WORKSPACE):
        raise RuntimeInvalidRequestError("WorkBuddy session is outside the installed workspace")
    return WORKSPACE


def normalized_config(values: Mapping[str, Any]) -> dict[str, Any]:
    if set(values) - set(DEFAULTS):
        raise RuntimeInvalidRequestError("Unknown WorkBuddy runtime configuration")
    result = {**DEFAULTS, **dict(values)}
    result["workspace"] = require_workspace(result["workspace"])
    for field in ("nodePath", "helperPath"):
        if not isinstance(result[field], str) or not ntpath.isabs(result[field]):
            raise RuntimeInvalidRequestError(f"{field} must be an absolute path")
    for field, minimum, maximum in (("requestTimeoutSeconds", 5, 120), ("pollIntervalSeconds", 1, 30)):
        value = result[field]
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not minimum <= value <= maximum:
            raise RuntimeInvalidRequestError(f"Invalid {field}")
    return result


class WorkBuddyProvider(RuntimeProvider):
    @property
    def runtime_type(self) -> str:
        return "workbuddy"

    @property
    def display_name(self) -> str:
        return "WorkBuddy"

    @property
    def implementation_type(self) -> str:
        return "local-service"

    async def get_config_schema(self) -> RuntimeConfigSchema:
        return RuntimeConfigSchema(
            runtime="workbuddy", revision=1,
            schema={"type": "object", "additionalProperties": False, "properties": {
                "nodePath": {"type": "string", "title": "Node executable"},
                "helperPath": {"type": "string", "title": "WorkBuddy native RPC helper"},
                "workspace": {"type": "string", "const": WORKSPACE, "title": "Workspace"},
                "requestTimeoutSeconds": {"type": "number", "minimum": 5, "maximum": 120},
                "pollIntervalSeconds": {"type": "number", "minimum": 1, "maximum": 30},
            }},
            defaults=DEFAULTS,
            metadata={"storageMode": "workbuddy-native", "sameSessionWriterLimit": 1},
        )

    async def discover(self) -> RuntimeTypeDescriptor:
        available = Path(DEFAULTS["nodePath"]).is_file() and Path(DEFAULTS["helperPath"]).is_file()
        return RuntimeTypeDescriptor(
            runtime_type="workbuddy", display_name="WorkBuddy", available=available,
            description="WorkBuddy native desktop conversations", implementation_type="local-service",
            reason=None if available else "WorkBuddy native RPC helper is not installed",
            config_schema=await self.get_config_schema(),
            capabilities={"listSessions": True, "getSession": True, "startTurn": True, "interrupt": True, "attachments": False},
            metadata={"storageMode": "workbuddy-native", "configured": False},
        )

    async def validate_config(self, values: Mapping[str, Any]) -> RuntimeConfig:
        normalized = normalized_config(values)
        schema = await self.get_config_schema()
        return RuntimeConfig(
            runtime="workbuddy", revision=1, values=normalized, schema=schema.schema,
            metadata={"storageMode": "workbuddy-native"},
        )

    async def create_runtime(self, config: RuntimeConfig, host: RuntimeHostClient):
        from .runtime import WorkBuddyRuntime
        return WorkBuddyRuntime(config, host, WorkBuddyBridge(normalized_config(config.values)))

    def resource_claims(self, config: RuntimeConfig) -> tuple[RuntimeResourceClaim, ...]:
        return (RuntimeResourceClaim(kind="workbuddy_native", key=filesystem_resource_key(str(config.values.get("helperPath", DEFAULTS["helperPath"]))), label="WorkBuddy native desktop"),)

    def session_source_key(self, config: RuntimeConfig) -> RuntimeSourceKey:
        return RuntimeSourceKey(kind="workbuddy_native", key=filesystem_resource_key(str(config.values.get("helperPath", DEFAULTS["helperPath"]))))
